```csharp
public class PatchManager : INotifyCollectionChangeHandler<string>, IDisposable
{
   private readonly string _patchFolderPath;

   public event Action OnDownloadStarted;
   public event Action<int?> OnProgressChanged;

   public PatchManager() => InitializePaths();

   void InitializePaths(){
       var appDirectoryInfo = Directory.GetParent(ApplicationHostingEnvironment.BaseUrl);
       _patchFolderPath = Path.Combine(appDirectoryInfo!.FullName,"patch");

       if(!Exists(_patchFolderPath)){
           try{ MakeDirectoriesRecursively(_patchFolderPath); } catch(Exception ex){ Console.WriteLine($"Erro criando diretório '{ex}' ");}
         }
     }

   bool Exists([NotNullAttribute] string path)=>{ return !string.IsNullOrEmpty(path)? Directory.Exists(path):false;}

   static void MakeDirectoriesRecursively([NotNullAttribute] string dirname )=> Directory.CreateDirectory(dirname );

   // Lógica adicional aqui ...
}

